package com.nextdigital.oncall.telegram.service;

import java.util.UUID;

import com.nextdigital.oncall.dto.telegram.TelegramLinkResponse;

/**
 * Service for managing Telegram bot integration.
 * Handles user linking, notifications, and bot lifecycle per on-call group.
 */
public interface TelegramBotService {

    /**
     * Links a Telegram chat to a Person account using a verification code.
     *
     * @param code the verification code generated by the bot via /start
     * @return response indicating success or failure
     */
    TelegramLinkResponse linkTelegramAccount(String code);

    /**
     * Returns the link status for a given code without consuming it.
     *
     * @param code the verification code
     * @return response with current status
     */
    TelegramLinkResponse getLinkStatus(String code);

    /**
     * Registers a bot for an on-call group (starts polling or sets webhook).
     *
     * @param groupId the on-call group ID
     */
    void registerGroupBot(UUID groupId);

    /**
     * Unregisters a bot for an on-call group (stops polling or removes webhook).
     *
     * @param groupId the on-call group ID
     */
    void unregisterGroupBot(UUID groupId);

    /**
     * Initializes all bots for groups with telegram_bot_enabled = true.
     * Called at application startup.
     */
    void initializeAllBots();
}
